/**
 *
 * FileUploadItem is a container component for a single file in the upload list.
 *
 * [Live Demo](https://www.primereact.org/fileupload/)
 *
 * @module FileUploadItem
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { FileUploadRootInstance } from './FileUploadRoot.types';
/**
 * Defines passthrough(pt) options type in FileUploadItem component.
 */
export type FileUploadItemPassThroughType<E> = PassThroughType<FileUploadItemInstance, E>;
/**
 * Defines passthrough(pt) options of FileUploadItem component.
 */
export interface FileUploadItemPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: FileUploadItemPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in FileUploadItem component.
 */
export interface FileUploadItemProps extends BaseComponentProps<FileUploadItemInstance, unknown, FileUploadItemPassThrough> {
    /**
     * The file object to display.
     */
    file?: File;
    /**
     * The index of the file in the list.
     */
    index?: number;
}
/**
 * Defines valid state in FileUploadItem component.
 */
export interface FileUploadItemState {
}
/**
 * Defines the methods and properties exposed by FileUploadItem component.
 */
export interface FileUploadItemExposes {
    /**
     * Instance of the FileUpload component.
     */
    fileupload: FileUploadRootInstance | undefined | null;
    /**
     * The file object.
     */
    file: File | undefined;
    /**
     * The index of the file in the list.
     */
    index: number | undefined;
    /**
     * Whether the file belongs to the uploaded files list.
     */
    uploaded: boolean;
    /**
     * Removes the file from its list (pending or uploaded), inferred from the file's current list.
     * @returns void
     */
    remove: () => void;
}
/**
 * Defines the CSS class names used in the FileUploadItem component.
 */
export declare const FileUploadItemClassNames: {
    /**
     * Class name of the root element
     */
    readonly root: "p-fileupload-file";
};
/**
 * Type representing the CSS class names used in the FileUploadItem component.
 */
export type FileUploadItemClassNamesType = (typeof FileUploadItemClassNames)[keyof typeof FileUploadItemClassNames];
/**
 * Instance of FileUploadItem component.
 */
export type FileUploadItemInstance = ComponentInstance<FileUploadItemProps, FileUploadItemState, FileUploadItemExposes>;
